Analise o trecho de código C++ a seguir responsável pelo ciclo de vida de conexões e sessões de usuários. Identifique falhas de gerenciamento de memória dinâmica e ciclo de vida de ponteiros no Heap, descrevendo a causa raiz, os riscos operacionais e apresentando o refatoramento defensivo com Modern C++.

```
#include <iostream>
#include <string>
#include <vector>

struct UserSession {
    uint32_t session_id;
    std::string username;
    bool is_authenticated;
    void log_activity() {
        std::cout << "[Session " << session_id << "] User: " << username << " is active.\n";
    }
};

class SessionRegistry {
private:
    std::vector<UserSession*> active_sessions;

public:
    void register_session(UserSession* session) {
        active_sessions.push_back(session);
    }

    void terminate_session(uint32_t session_id) {
        for (auto it = active_sessions.begin(); it != active_sessions.end(); ++it) {
            if ((*it)->session_id == session_id) {
                delete *it; // Liberação da memória alocada no Heap
                // Inseguro: ponteiro pendente (dangling pointer) não foi removido do vetor nem aterrado (nullptr)
                break;
            }
        }
    }

    void audit_all_sessions() {
        std::cout << "[*] Executando auditoria periodica de sessoes...\n";
        for (UserSession* session : active_sessions) {
            // Acesso desreferenciando o ponteiro
            session->log_activity();
        }
    }
};
```

