Audite a rotina de verificação de autenticação JWT em Node.js apresentada abaixo. Avalie as vulnerabilidades relacionadas à manipulação do cabeçalho do token (`alg`), descreva o ataque de confusão de chave assimétrica para simétrica e forneça o código seguro com validação estrita.

```
const jwt = require('jsonwebtoken');
const fs = require('fs');

const publicKey = fs.readFileSync('./public.pem', 'utf8');

function authenticateRequest(req, res, next) {
    const authHeader = req.headers['authorization'];
    if (!authHeader) {
        return res.status(401).json({ error: "Token ausente" });
    }

    const token = authHeader.split(' ')[1];

    try {
        // Inseguro: a biblioteca confia cegamente no parametro 'alg' do header do token
        const decoded = jwt.verify(token, publicKey);
        req.user = decoded;
        next();
    } catch (err) {
        return res.status(403).json({ error: "Token invalido" });
    }
}
```

Audite a rotina de processamento financeiro escrita em Go apresentada abaixo. Avalie o tratamento de concorrência, o comportamento das goroutines perante o estado compartilhado da memória e proponha a solução de sincronização atômica adequada.

```
package main

import (
	"errors"
	"fmt"
	"time"
)

type Account struct {
	ID      string
	Balance float64
}

type BankService struct {
	accounts map[string]*Account
}

func (s *BankService) Withdraw(accountID string, amount float64) error {
	account, exists := s.accounts[accountID]
	if !exists {
		return errors.New("conta nao encontrada")
	}

	// Verificação do saldo disponível (Time-of-Check)
	if account.Balance < amount {
		return errors.New("saldo insuficiente")
	}

	// Simulação de latência de I/O ou processamento assíncrono
	time.Sleep(10 * time.Millisecond)

	// Atualização do saldo (Time-of-Use)
	account.Balance -= amount
	fmt.Printf("[Transferencia] Conta %s: debito de %.2f concluido. Novo saldo: %.2f\n",
		accountID, amount, account.Balance)

	return nil
}
```

