```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>

#define MAX_PAYLOAD 1024

void process_packet(int sock) {
    short payload_len;
    char buffer[MAX_PAYLOAD];

    // Lê o cabeçalho de comprimento enviado pelo cliente (2 bytes)
    if (recv(sock, &payload_len, sizeof(payload_len), 0) != sizeof(payload_len)) {
        return;
    }

    // Validação ingênua de limite
    if (payload_len > MAX_PAYLOAD) {
        printf("[!] Tamanho excede o limite permitido.\n");
        return;
    }

    // Leitura do corpo da mensagem para o buffer local na stack
    ssize_t bytes_read = recv(sock, buffer, payload_len, 0);
    if (bytes_read > 0) {
        buffer[bytes_read - 1] = '\0';
        printf("[*] Pacote recebido: %s\n", buffer);
    }
}
```

