```
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract EtherVault {
    mapping(address => uint256) public userBalances;

    function deposit() external payable {
        require(msg.value > 0, "Valor deve ser maior que zero");
        userBalances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(userBalances[msg.sender] >= amount, "Saldo insuficiente");

        // Transferencia externa via chamada de baixo nivel enviando ether
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Falha na transferencia");

        // Atualizacao de estado (saldo) apos a chamada externa
        userBalances[msg.sender] -= amount;
    }
}
