import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.Base64;
import javax.servlet.http.HttpServletRequest;

public class SessionTokenHandler {

    public Object restoreSession(HttpServletRequest request) throws Exception {
        String sessionCookie = request.getHeader("X-Custom-Session");
        if (sessionCookie == null || sessionCookie.isEmpty()) {
            return null;
        }

        // Decodifica a carga útil enviada pelo cliente em base64
