package main

import (
	"errors"
	"fmt"
	"time"
)

type Account struct {
	ID      string
	Balance float64
}

type BankService struct {
	accounts map[string]*Account
}

func (s *BankService) Withdraw(accountID string, amount float64) error {
	account, exists := s.accounts[accountID]
	if !exists {
		return errors.New("conta nao encontrada")
	}

	// Verificação do saldo disponível (Time-of-Check)
	if account.Balance < amount {
		return errors.New("saldo insuficiente")
	}

	// Simulação de latência de I/O ou processamento assíncrono
	time.Sleep(10 * time.Millisecond)

	// Atualização do saldo (Time-of-Use)
	account.Balance -= amount
	fmt.Printf("[Transferencia] Conta %s: debito de %.2f concluido. Novo saldo: %.2f\n",
		accountID, amount, account.Balance)

	return nil
}
